-- Etapa 7B, Bloco B: conhecimento conforme as decisões do dono (Pix primeiro, parcelamento sob demanda, nota fiscal, troca,
-- tom, avaliação no Google, BauerLab, urgência, dados do cliente). Idempotente. Tudo nasce com revisar = true.
-- Os vetores são refeitos pela função "conhecimento" (embedding_em = null marca para reindexar).
insert into public.conhecimento (slug, titulo, categoria, quando_usar, resposta_pronta, fatos, proximo_passo, tags, fonte, revisar, ativo)
select v.slug, v.titulo, v.categoria, v.quando_usar, v.resposta_pronta, v.fatos, v.proximo_passo, v.tags, 'Etapa 7B', true, true
from (values
  ('pag-formas', 'Formas de pagamento (Pix primeiro)', 'pagamento', 'Cliente pergunta como pode pagar ou na hora de mandar o link.',
   'Você paga pelo link que eu te mando. O Pix é o mais rápido e vale de qualquer banco, cai na hora.',
   'Sempre apresente o Pix primeiro e diga que pode ser pago em qualquer banco. Não divulgue o parcelamento por conta própria. Desconto específico para Pix não existe ainda. Boleto não é aceito.',
   'Perguntar se prefere o Pix e mandar o link.', array['pagamento','pix','forma de pagamento']),
  ('pag-pix', 'Pix', 'pagamento', 'Cliente quer pagar no Pix ou pergunta se tem desconto no Pix.',
   'O Pix é ótimo, cai na hora e vale de qualquer banco. Te mando o link e é só escolher Pix.',
   'Não existe desconto para Pix; se o cliente pedir, não prometa. Quem paga e envia a arte até 12h começa a contar o prazo no mesmo dia.',
   'Mandar o link de pagamento.', array['pix','pagamento']),
  ('pag-parcelar', 'Parcelamento (só quando o cliente pergunta ou hesita)', 'pagamento', 'Cliente pergunta se dá para parcelar ou hesita por causa do valor.',
   'Dá sim, no cartão você consegue parcelar em até 2x sem juros pelo link. Se preferir, o Pix à vista também é bem prático.',
   'Até 2x SEM juros no cartão, para todos os pedidos. Nunca ofereça parcelamento antes de o cliente perguntar ou mostrar dificuldade com o valor. Acima de 2x não existe; se pedir, diga que vai confirmar e chame o dono. O 2x pode contar como vantagem na condição especial, mas só pela ferramenta.',
   'Mandar o link com a opção de cartão.', array['parcelar','parcelamento','cartao','2x']),
  ('pag-nf', 'Nota fiscal', 'pagamento', 'Cliente pergunta se emite nota fiscal.',
   'Emitimos nota fiscal sim, sempre que você quiser. Só preciso do CPF ou CNPJ e de um e-mail pra enviar.',
   'A empresa emite nota fiscal sempre que o cliente quiser. Peça CPF ou CNPJ, e-mail e endereço apenas quando ele quiser a nota. Não peça esses dados antes.',
   'Coletar documento e e-mail e salvar no contato.', array['nota fiscal','nf','cnpj','cpf']),
  ('troca-politica', 'Troca e reembolso [CONFIRMAR]', 'troca', 'Cliente pergunta sobre troca, devolução ou reembolso.',
   'Se tiver qualquer problema com o pedido, me conta que eu passo pro responsável resolver direitinho com você.',
   '[CONFIRMAR] A política de troca e reembolso ainda não foi definida pelo dono. Não prometa troca, devolução nem reembolso. Registre o caso e chame o dono com o resumo.',
   'Encaminhar ao dono com o resumo do caso.', array['troca','reembolso','devolucao','garantia']),
  ('tom-vendedor', 'Tom de vendedor humano', 'guia', 'Sempre. Lembrete de como conversar.',
   'Escute primeiro, devolva com as palavras do cliente, faça uma pergunta curta por vez e feche com um próximo passo simples.',
   'Mensagens curtas. Emoji com moderação. Abreviações naturais como vc, sem erro de português. kkkk ou rsrs só se o cliente abrir espaço. Em reclamação ou assunto sério, tom profissional e nenhum emoji. Sem travessão, sem lista, sem markdown. Prova social só com o que for verdade. Fechamento assumido: "Posso já te mandar o link?".',
   'Seguir o fluxo: entender, orçar, tirar dúvida, fechar.', array['tom','vendas','humano']),
  ('google-avaliacao', 'Avaliação no Google (depois da entrega)', 'posvenda', 'Depois da entrega, na mensagem de satisfação, se o cliente ficou satisfeito.',
   'Que bom que gostou! Se puder deixar uma avaliação pra gente no Google, ajuda muito: https://g.page/r/CZ6eNNGjdgO4EBM/review',
   'Peça de forma genuína, uma vez. NUNCA ofereça desconto, brinde ou qualquer benefício em troca da avaliação (as regras do Google proíbem). Não cobre nem confirme se avaliou.',
   'Agradecer e encerrar com abertura para um novo pedido.', array['avaliacao','google','posvenda']),
  ('bauerlab', 'BauerLab: site, marca e anúncios', 'empresa', 'Cliente precisa de site, marca, presença digital, divulgação ou anúncios.',
   'Pra isso eu indico a BauerLab, agência parceira de sites, landing pages, lojas virtuais, identidade visual, redes sociais, tráfego pago e Google Meu Negócio. O contato é o João Victor: +55 31 99802-1169.',
   'Apresente uma vez só, sem insistir e sem atrapalhar a venda em andamento. Depois volte ao pedido. Use a ferramenta que registra a oportunidade.',
   'Registrar a oportunidade e voltar ao pedido.', array['bauerlab','site','marca','anuncio','trafego']),
  ('urgencia', 'Cliente com urgência', 'prazos', 'Cliente diz que tem pressa ou precisa para uma data.',
   'Entendi a urgência. O prazo oficial é o que te passei, e eu já sinalizei aqui pra você ser atendido na frente.',
   'Nunca altere o prazo oficial nem prometa data que a ferramenta não deu. Registre a urgência no contato (selo no CRM). A contagem do prazo começa na aprovação da arte.',
   'Registrar a urgência e seguir o fluxo normal.', array['urgencia','prazo','pressa']),
  ('dados-cliente', 'Dados do cliente', 'qualificacao', 'Na hora de coletar dados.',
   'Pra seguir, me passa só o que falta: ',
   'Pergunte só o que ainda não está no CRM; a ferramenta de salvar contato devolve o que falta. CPF ou CNPJ e endereço só se o cliente quiser nota fiscal ou entrega. A pergunta sobre promoções é separada ("Quer receber novidades e promoções por aqui?") e nunca presumida.',
   'Salvar o contato com o que o cliente disse.', array['dados','cadastro','promocoes','consentimento'])
) as v(slug, titulo, categoria, quando_usar, resposta_pronta, fatos, proximo_passo, tags)
on conflict (slug) where slug is not null do update set titulo = excluded.titulo, categoria = excluded.categoria, quando_usar = excluded.quando_usar,
  resposta_pronta = excluded.resposta_pronta, fatos = excluded.fatos, proximo_passo = excluded.proximo_passo, tags = excluded.tags,
  fonte = 'Etapa 7B', revisar = true, embedding = null, embedding_em = null, atualizado_em = now();
